service.method:
/*ContactInfo.getPwResetFlag*/

	SELECT #DB_OWNER#NVL(PW_RESET_FLAG,'N') AS PW_RESET_FLAG
	FROM SUSMT
	WHERE HOUSE_CODE = ${session.HOUSE_CODE}
	AND USER_ID = ${session.ID}

/*ContactInfo.doSave*/

	UPDATE SADDR
	   SET PHONE_NO1 = ${CONTACT_NO},
	       PHONE_NO2 = ${MOBILE_NO},
	       CHANGE_DATE = ${current.DATE},
	       CHANGE_TIME = ${current.TIME},
	       CHANGE_USER_ID = ${session.ID}
	 WHERE HOUSE_CODE = ${session.HOUSE_CODE}
	   AND CODE_TYPE = 'USER'
	   AND CODE_NO = ${session.ID}
	   AND #DB_OWNER#NVL( DEL_FLAG , 'N' ) = 'N'

/*ContactInfo.updatePwResetFlag*/

	UPDATE SUSMT
	   SET PW_RESET_FLAG = 'Y',
	       CHANGE_DATE = ${current.DATE},
	       CHANGE_TIME = ${current.TIME},
	       CHANGE_USER_ID = ${session.ID}
	 WHERE HOUSE_CODE = ${session.HOUSE_CODE}
	   AND USER_ID = ${session.ID}
	   AND #DB_OWNER#NVL( DEL_FLAG , 'N' ) = 'N'
